      --danger: #ff6b81;
      --danger-strong: #ff4e67;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, #1d2440 0%, transparent 35%),
        linear-gradient(180deg, #0d1018 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #05070d;
      transform: translateY(-200%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem;
    }

    .preview-card {
      width: min(100%, 28rem);
      padding: 1.5rem;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
      box-shadow: var(--shadow);
      backdrop-filter: blur(10px);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.875rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 1rem;
      font-size: clamp(1.9rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    figure {
      margin: 1.5rem 0 1rem;
    }

    .image-shell {
      position: relative;
      overflow: hidden;
      min-height: 19rem;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--radius);
      background:
        linear-gradient(135deg, rgba(132, 169, 255, 0.35), rgba(17, 21, 34, 0.2)),
        linear-gradient(180deg, #273252, #131827);
    }

    .image-shell img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    figcaption {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      margin-top: 0.85rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .button-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-top: 1.5rem;
      flex-wrap: wrap;
    }

    button {
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.85rem 1.25rem;
      font: inherit;
      font-weight: 700;
      color: var(--text);
      cursor: pointer;
      transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    .skip-link:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
    }

    .ghost {
      background: rgba(255, 255, 255, 0.05);
      border-color: rgba(255, 255, 255, 0.08);
    }

    .trigger,
    .danger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      box-shadow: 0 12px 24px rgba(255, 78, 103, 0.25);
    }

    .status {
      min-height: 1.5rem;
      margin-top: 1rem;
      color: #ffd1d8;
      font-weight: 700;
    }

    dialog {
      width: min(100% - 2rem, 28rem);
      padding: 0;
      border: 1px solid var(--border);
      border-radius: 24px;
      background: linear-gradient(180deg, var(--panel-strong), var(--panel));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 4, 10, 0.72);
      backdrop-filter: blur(4px);
    }

    .dialog-content {
      padding: 1.5rem;
    }

    .dialog-title {
      margin: 0 0 0.75rem;
      font-size: 1.35rem;
    }

    .dialog-copy {
      margin-bottom: 1.5rem;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .deleted .image-shell {
      display: grid;
      place-items: center;
      padding: 2rem;
      color: var(--muted);
      text-align: center;
    }

    .deleted img,
    .deleted .trigger {
      display: none;
    }

    @media (max-width: 480px) {
      main {
        padding: 1rem;
      }

      .preview-card,
      .dialog-content {
        padding: 1.25rem;
      }

      .button-row,
      .dialog-actions {
        flex-direction: column;
        align-items: stretch;
      }

      button {
        width: 100%;
      }

      figcaption {
        flex-direction: column;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
        --panel-strong: Canvas;
        --border: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
      }

      body,
      .preview-card,
      .image-shell,
      dialog,
      button {
        border-color: ButtonBorder;
      }

      .trigger,
      .danger,
      .ghost,
      .skip-link {
        background: ButtonFace;
        color: ButtonText;
        box-shadow: none;
      }

      dialog::backdrop {
        background: rgba(0, 0, 0, 0.6);
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="preview-card" aria-labelledby="page-title">
      <p class="eyebrow">Image library</p>
      <h1 id="page-title">Image preview</h1>
      <p>Review the selected image before keeping it in your collection or removing it from your library.</p>

      <figure id="image-preview">
        <div class="image-shell">
          <img
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80"
            alt="Golden light across a mountain lake with evergreen trees"
          >
        </div>
        <figcaption>
          <span>Mountain Lake</span>
          <span>4.8 MB JPG</span>
        </figcaption>
      </figure>

      <div class="button-row">
        <p>Deleting removes this image from your saved library.</p>
        <button type="button" class="trigger" id="open-dialog">Delete image</button>
      </div>

      <p class="status" id="status-message" aria-live="polite"></p>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
      <p class="dialog-copy" id="dialog-description">This will permanently remove <strong>Mountain Lake</strong> from your library.</p>
      <div class="dialog-actions">
        <button type="button" class="ghost" id="cancel-dialog">Keep image</button>
        <button type="button" class="danger" id="confirm-delete">Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openButton = document.getElementById('open-dialog');
    const cancelButton = document.getElementById('cancel-dialog');
    const confirmButton = document.getElementById('confirm-delete');
    const preview = document.getElementById('image-preview');
    const statusMessage = document.getElementById('status-message');
    let returnFocusTo = openButton;

    openButton.addEventListener('click', () => {
      returnFocusTo = document.activeElement;
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close();
    });

    dialog.addEventListener('close', () => {
      if (returnFocusTo && document.contains(returnFocusTo) && !openButton.disabled) {
        returnFocusTo.focus();
      }
    });

    confirmButton.addEventListener('click', () => {
      preview.classList.add('deleted');
      preview.querySelector('.image-shell').textContent = 'This image has been deleted from your library.';
      preview.querySelector('figcaption').innerHTML = '<span>Deleted just now</span><span>Preview unavailable</span>';
      openButton.disabled = true;
      openButton.setAttribute('aria-disabled', 'true');
      statusMessage.textContent = 'Image deleted from your library.';
      dialog.close();
    });
  </script>
</body>
</html>
